/**
 * Owner-only. Returns up to the last 50 runtime errors captured by the
published app sandbox (`window.error` and `window.unhandledrejection`).
Used by the panel to show the user when a real visitor hit a blank
page, so they can regenerate the app.

 * @summary List recent JavaScript errors reported from the published app's iframe
 */
export const ListAppRuntimeErrorsParams = zod.object({
  id: zod.coerce.number(),
});

export const ListAppRuntimeErrorsResponse = zod.object({
  errors: zod.array(
    zod
      .object({
        id: zod.number(),
        kind: zod
          .string()
          .describe(
            "error | unhandledrejection (matches the browser event name).",
          ),
        message: zod.string(),
        source: zod.string().nullish(),
        lineno: zod.number().nullish(),
        colno: zod.number().nullish(),
        stack: zod.string().nullish(),
        userAgent: zod.string().nullish(),
        pathname: zod
          .string()
          .nullish()
          .describe("SPA route the visitor was on when the error fired."),
        createdAt: zod.coerce.date(),
      })
      .describe(
        "A single JS error captured by the published app's iframe sandbox.",
      ),
  ),
});

/**
 * Owner-only. Used after the user regenerates or fixes the app and
wants to dismiss the error notice in the panel.

 * @summary Discard all stored runtime errors for this app
 */
export const ClearAppRuntimeErrorsParams = zod.object({
  id: zod.coerce.number(),
});

/**
 * @summary Push the app source to GitHub. Idempotent: the FIRST push creates a
new public repo under the connected account; subsequent pushes add
a fresh commit on `main` to the same repo (replacing the file tree
with the current snapshot, so deleted files are also removed).

 */
export const PushAppToGitHubParams = zod.object({
  id: zod.coerce.number(),
});

export const PushAppToGitHubResponse = zod.object({
  url: zod.string(),
  repoFullName: zod.string(),
  updated: zod
    .boolean()
    .describe(
      "true → the existing repo received a new commit on `main`.\nfalse → a brand-new repo was created (first push, or previous\nrepo was deleted on GitHub).\n",
    ),
});

/**
 * @summary Poll the status of a generation job
 */
export const GetGenerationJobParams = zod.object({
  id: zod.coerce.number(),
});

export const getGenerationJobResponseProgressMin = 0;
export const getGenerationJobResponseProgressMax = 100;

export const GetGenerationJobResponse = zod.object({
  id: zod.number(),
  status: zod.string().describe("queued | running | succeeded | failed"),
  phase: zod
    .string()
    .describe(
      "queued | starting | researching | generating | parsing | ready | failed",
    ),
  progress: zod
    .number()
    .min(getGenerationJobResponseProgressMin)
    .max(getGenerationJobResponseProgressMax),
  appId: zod.number().nullish(),
  errorMessage: zod.string().nullish(),
  createdAt: zod.coerce.date(),
  updatedAt: zod.coerce.date(),
});

/**
 * Returns log lines emitted by individual agents (researcher, architect,
designer, integration, coder, qa, validator, patcher, system) during
the generation pipeline. Pass `afterId` to fetch only lines newer than
the last id you've seen — the dashboard polls this endpoint every
~1.2s while a job is running so the user sees the agents' real-time
output.

 * @summary Stream live agent log lines for a job
 */
export const GetGenerationJobLogsParams = zod.object({
  id: zod.coerce.number(),
});

export const getGenerationJobLogsQueryAfterIdDefault = 0;
export const getGenerationJobLogsQueryAfterIdMin = 0;

export const GetGenerationJobLogsQueryParams = zod.object({
  afterId: zod.coerce
    .number()
    .min(getGenerationJobLogsQueryAfterIdMin)
    .default(getGenerationJobLogsQueryAfterIdDefault),
});

export const GetGenerationJobLogsResponse = zod.object({
  logs: zod.array(
    zod
      .object({
        id: zod
          .number()
          .describe(
            "Monotonic id; pass the highest seen value as `afterId` on the next poll.",
          ),
        agent: zod
          .string()
          .describe(
            "Originating agent (researcher | architect | designer | integration | coder | qa | validator | patcher | system).",
          ),
        level: zod.enum(["info", "warn", "error"]),
        message: zod.string(),
        createdAt: zod.coerce.date(),
      })
      .describe(
        "A single live log line emitted by an agent during generation.",
      ),
  ),
});

